procedure WriteArray<T>(a: array of T; delimiter: string := ' ');
begin
  if (a=nil) or (a.Length=0) then
    exit;
  for var i := 0 to a.Length - 2 do
    write(a[i], delimiter);
  write(a[a.Length - 1]);  
end;

procedure WritelnArray<T>(a: array of T; delimiter: string := ' ');
begin
  WriteArray(a, delimiter);
  writeln;
end;

